script:
frappe.ui.form.on("Item",{
	refresh: function(frm){
	    if (frm.doc.barcodes.length === 0){
		    frm.add_custom_button("Generate Barcode", function(){
    			frappe.call({
    				method: "impex.barcode.barcode.generate_barcode",
    				args: {"docname": frm.doc.name},
    				callback: function(r){
                        console.log(r.message)
    					var row = frm.add_child("barcodes");
                        row.barcode = r.message;
                        row.barcode_image = r.message.toString();
                        frm.refresh_field('barcodes');
                        cur_frm.$wrapper.find('[data-fieldname="barcode_image"]')[1].click()
                        cur_frm.$wrapper.find('[data-fieldname="barcode_image"]')[1].click()
                        frm.save()
    				}
    
    			})
    		}, __("Actions"))
	    }
	}
})

frappe.ui.form.on('Purchase Receipt', {
	refresh: function(frm) {
        frm.doc.items.forEach(function(item) {
            // Directly modify the field value without using frappe.model.set_value
            item.custom_label_qty = item.qty;
        });
        // Refresh the field to reflect changes in the UI
        frm.refresh_field('items');
    }
})
